    import re
    import asyncio

    # No knowledge-base helper functions are available for this task.

    # 1) Reset any existing filters to ensure the product list is visible
    try:
        # The Reset Filter and Search buttons live inside a table cell called "Reset Filter Search"
        reset_cell = page.get_by_role("cell", name="Reset Filter Search")
        await reset_cell.get_by_role("button", name="Reset Filter").click()
        await page.wait_for_load_state("networkidle")
        await asyncio.sleep(0.3)
    except Exception:
        # If the specific cell isn't available for some reason, try a top-level Reset Filter button
        try:
            await page.get_by_role("button", name="Reset Filter").click()
            await page.wait_for_load_state("networkidle")
            await asyncio.sleep(0.3)
        except Exception:
            # Not fatal — continue and try searching anyway
            pass

    # 2) Click the Search button in the filter area to refresh results
    try:
        reset_cell = page.get_by_role("cell", name="Reset Filter Search")
        await reset_cell.get_by_role("button", name="Search").click()
        await page.wait_for_load_state("networkidle")
        await asyncio.sleep(0.4)
    except Exception:
        try:
            await page.get_by_role("button", name="Search").click()
            await page.wait_for_load_state("networkidle")
            await asyncio.sleep(0.4)
        except Exception:
            # If Search can't be clicked, continue — the table may already be refreshed
            pass

    # 3) Find and open the product edit page for "Minerva LumaTech V-Tee"
    product_clicked = False
    product_name_re = re.compile(r"Minerva LumaTech V-Tee", re.I)
    try:
        # Prefer a row-scoped link to avoid ambiguity
        product_row = page.get_by_role("row", name=product_name_re)
        await product_row.get_by_role("link", name=product_name_re).click()
        await page.wait_for_load_state("networkidle")
        product_clicked = True
    except Exception:
        # Fallback: try a page-level link
        try:
            await page.get_by_role("link", name=product_name_re).click()
            await page.wait_for_load_state("networkidle")
            product_clicked = True
        except Exception:
            product_clicked = False

    if not product_clicked:
        # If product still not visible, raise so the caller knows we couldn't continue
        raise Exception('Could not locate product "Minerva LumaTech V-Tee" in the product grid')

    # 4) On the product edit page: open the Custom Options tab
    await asyncio.sleep(0.6)
    opened_custom = False
    try:
        await page.get_by_role("tab", name="Custom Options").click()
        opened_custom = True
    except Exception:
        try:
            await page.get_by_role("link", name="Custom Options").click()
            opened_custom = True
        except Exception:
            try:
                await page.get_by_role("button", name="Custom Options").click()
                opened_custom = True
            except Exception:
                opened_custom = False

    if not opened_custom:
        raise Exception('Could not open the Custom Options tab for the product')

    await asyncio.sleep(0.6)

    # 5) Add a new drop-down option titled "Size"
    # Try several likely button labels for adding an option
    add_clicked = False
    for name in ("Add New Option", "Add Option", "Add New Option +", "Add New Option+"):
        try:
            await page.get_by_role("button", name=name).click()
            add_clicked = True
            break
        except Exception:
            continue

    if not add_clicked:
        # As a fallback, click the first button that contains the text 'Add' in its inner text
        try:
            btns = page.get_by_role("button")
            btn_count = await btns.count()
            for i in range(btn_count):
                try:
                    text = (await btns.nth(i).inner_text()).strip()
                except Exception:
                    text = ""
                if 'Add' in text:
                    await btns.nth(i).click()
                    add_clicked = True
                    break
        except Exception:
            add_clicked = False

    await asyncio.sleep(0.5)

    # 6) Fill the new option title as 'Size' and set type to 'Drop-down'
    try:
        title_boxes = page.get_by_role("textbox", name="Title")
        tcount = await title_boxes.count()
        if tcount > 0:
            # Fill the last Title textbox (new option typically appears at the end)
            await title_boxes.nth(tcount - 1).fill("Size")
        else:
            # fallback: fill a last empty textbox found on the page
            all_textboxes = page.get_by_role("textbox")
            total = await all_textboxes.count()
            filled = False
            for i in range(total - 1, -1, -1):
                try:
                    val = await all_textboxes.nth(i).input_value()
                except Exception:
                    val = None
                if not val:
                    await all_textboxes.nth(i).fill("Size")
                    filled = True
                    break
            if not filled and total > 0:
                await all_textboxes.nth(0).fill("Size")
    except Exception:
        # continue even if title couldn't be set (so failure will be visible on Save)
        pass

    try:
        type_boxes = page.get_by_role("combobox", name="Type")
        type_count = await type_boxes.count()
        if type_count > 0:
            await type_boxes.nth(type_count - 1).select_option(label="Drop-down")
        else:
            await page.get_by_role("combobox").first.select_option(label="Drop-down")
    except Exception:
        # ignore if not present
        pass

    await asyncio.sleep(0.4)

    # 7) Add the option value 'XXXL' — attempt to fill the most-recent / nearby Title textbox
    try:
        title_boxes = page.get_by_role("textbox", name="Title")
        tcount = await title_boxes.count()
        if tcount >= 2:
            # assume the last Title textbox is the option value
            await title_boxes.nth(tcount - 1).fill("XXXL")
        else:
            # fallback: try a few of the last textboxes on the page
            all_textboxes = page.get_by_role("textbox")
            total = await all_textboxes.count()
            for idx in range(total - 1, max(-1, total - 6), -1):
                try:
                    await all_textboxes.nth(idx).fill("XXXL")
                    break
                except Exception:
                    continue
    except Exception:
        pass

    await asyncio.sleep(0.4)

    # 8) Save the product (final action - may navigate away)
    try:
        await page.get_by_role("button", name="Save").click()
        # do not attempt further selectors after this navigation
    except Exception:
        try:
            await page.get_by_role("button", name="Save and Continue Edit").click()
        except Exception:
            await page.get_by_role("button", name=re.compile(r"Save", re.I)).click()
            return total

